/* Binds retained diorama names to the splats generated by the current bake. */
(function (K) {
  const A = K.authoring;
  const record = value => value && Object.getPrototypeOf(value) === Object.prototype;
  const positive = value => Number.isFinite(value) && value > 0;
  const budget = (value, max) => Number.isSafeInteger(value) && value > 0 && value <= max;
  const groupFields = new Set(['id', 'parts', 'anchor', 'breakable', 'static', 'mass', 'strength', 'mode', 'fragmentSize']);
  const validRef = /^(solid|part|stroke):.+$/;

  function prepare(scene) {
    const spec = scene.breakables;
    if (spec == null) return;
    if (!record(spec) || Object.keys(spec).some(key => !['groups', 'links', 'support'].includes(key)) ||
        !Array.isArray(spec.groups) || !budget(spec.groups.length, 4096) ||
        spec.links !== undefined && (!Array.isArray(spec.links) || spec.links.length > 16384) ||
        spec.support !== undefined && typeof spec.support !== 'boolean') {
      throw new TypeError('Expected breakables with named groups and optional links or support');
    }
    const available = new Set();
    for (const solid of Array.isArray(scene.solids) ? scene.solids : []) {
      if (!solid || solid.carve || solid.hold) continue;
      if (solid.id) available.add('solid:' + solid.id);
      if (solid.part) available.add('part:' + solid.part);
    }
    const strokes = scene.brushRegion?.strokes;
    for (const stroke of Array.isArray(strokes) ? strokes : [])
      if (['sculpt', 'place', 'scatter'].includes(stroke?.mode)) available.add('stroke:' + stroke.id);
    const ids = new Map(), claimed = new Set();
    for (const group of spec.groups) {
      if (!record(group) || Object.keys(group).some(key => !groupFields.has(key)) ||
          !TargetSelectors.name(group.id) || ids.has(group.id) || !Array.isArray(group.parts) || !budget(group.parts.length, 16384))
        throw new TypeError('Each breakable group needs a distinct id and an array of authored parts');
      for (const ref of group.parts) {
        if (typeof ref !== 'string' || !validRef.test(ref) || !available.has(ref)) throw new RangeError('Unknown breakable part: ' + ref);
        if (claimed.has(ref)) throw new RangeError('Breakable parts must belong to a single group: ' + ref);
        claimed.add(ref);
      }
      if (['anchor', 'breakable', 'static'].some(key => group[key] !== undefined && typeof group[key] !== 'boolean') ||
          ['mass', 'strength'].some(key => group[key] !== undefined && !positive(group[key])) ||
          group.mode !== undefined && !['rubble', 'debris'].includes(group.mode) ||
          group.fragmentSize !== undefined && (!Number.isFinite(group.fragmentSize) || group.fragmentSize < 0))
        throw new RangeError('Invalid breakable settings for ' + group.id);
      ids.set(group.id, []);
    }
    const links = spec.links ?? [], linked = new Set();
    for (const link of links) {
      if (!Array.isArray(link) || link.length !== 2 || link[0] === link[1] || !link.every(id => ids.has(id)))
        throw new RangeError('Breakable links need two distinct known group ids');
      const key = JSON.stringify(link.slice().sort());
      if (linked.has(key)) throw new RangeError('Breakable links must be distinct');
      linked.add(key);
      ids.get(link[0]).push(link[1]);
      ids.get(link[1]).push(link[0]);
    }
    if (spec.support ?? links.length > 0) {
      const queue = spec.groups.filter(group => group.anchor).map(group => group.id), reached = new Set(queue);
      for (let i = 0; i < queue.length; i++) for (const id of ids.get(queue[i])) {
        if (reached.has(id)) continue;
        reached.add(id); queue.push(id);
      }
      if (reached.size !== ids.size) throw new RangeError('Every supported breakable group must connect to an anchor');
    }
    return spec;
  }

  function references(target, metadata, i, bySolid) {
    const entity = metadata?.targets?.[metadata.targetIds?.[i]]?.entity;
    if (target.surface === 'brush-region' && typeof target.entity === 'string' && target.entity.startsWith('brush-stroke:'))
      return ['stroke:' + target.entity.slice('brush-stroke:'.length)];
    const result = [];
    if (bySolid?.has(entity)) result.push('solid:' + entity);
    if (typeof target.object === 'string' && (entity === undefined || bySolid?.get(entity) === target.object))
      result.push('part:' + target.object);
    return result;
  }

  const catalogs = new WeakMap();
  function bind(world, scene, spec) {
    const bySolid = new Map(scene.solids?.filter(solid => solid.id).map(solid => [solid.id, solid.part]));
    catalogs.set(world, bySolid);
    if (!spec) return world;
    const parts = new Map(), byGroup = spec.groups.map(() => []);
    spec.groups.forEach((group, index) => {
      for (const ref of group.parts) parts.set(ref, { index, count: 0 });
    });
    const rows = TargetSelectors.index(world), matched = new Map();
    for (let i = 0; i < world.count; i++) {
      if (world.data[i * 16 + 3] <= 0) continue;
      const target = rows.row(i);
      if (!matched.has(target)) matched.set(target, references(target, world.renderMetadata, i, bySolid).map(ref => parts.get(ref)).filter(Boolean));
      const matches = matched.get(target);
      if (!matches.length) continue;
      const index = matches[0].index;
      for (const part of matches) {
        if (part.index !== index) throw new RangeError('Authored breakable groups overlap at ' + (target.entity ?? target.object));
        part.count++;
      }
      byGroup[index].push(i);
    }
    for (const [ref, part] of parts) if (!part.count) throw new RangeError('Breakable part has no visible splats: ' + ref);
    world.breakables = Object.freeze({
      groups: Object.freeze(spec.groups.map((group, i) => Object.freeze({
        ...group, parts: Object.freeze(group.parts.slice()), ids: Object.freeze(byGroup[i])
      }))),
      links: Object.freeze((spec.links ?? []).map(link => Object.freeze(link.slice()))),
      support: spec.support
    });
    return world;
  }

  function suggest(world, { at, radius = 1, voxel = radius / 10, maxSamples = 20000, minSamples = 4, exclude = [] } = {}) {
    if (!(world?.data instanceof Float32Array) || !Number.isSafeInteger(world.count) || world.count < 0 || world.count * 16 > world.data.length || !Array.isArray(at) || at.length !== 3 ||
        ![...at].every(Number.isFinite) || !positive(radius) || !Number.isFinite(radius ** 2) || !positive(voxel) || voxel > radius || radius / voxel > 128 ||
        !budget(maxSamples, 250000) || !budget(minSamples, maxSamples) || !Array.isArray(exclude))
      throw new RangeError('Breakable suggestion needs a finite position and bounded search settings');
    const rows = TargetSelectors.index(world), owners = new Map(), blocked = new Set(exclude);
    for (const group of world.breakables?.groups ?? [])
      if (group.anchor || group.breakable === false) for (const ref of group.parts) blocked.add(ref);
    const cells = new Map(), totals = new Map();
    const D = world.data, bySolid = catalogs.get(world), r2 = radius ** 2, edge = (radius - voxel) ** 2;
    let nearest = Infinity, seed, count = 0;
    for (let i = 0; i < world.count; i++) {
      const q = i * 16;
      if (!(D[q + 3] > 0)) continue;
      const target = rows.row(i);
      if (!owners.has(target)) {
        const refs = references(target, world.renderMetadata, i, bySolid);
        const ref = refs.find(name => name.startsWith('part:')) ?? refs[0];
        const owner = ref ?? target.entity ?? target.object ?? null;
        owners.set(target, { owner, ref, blocked: refs.some(ref => blocked.has(ref)) });
      }
      const { owner, ref, blocked: skip } = owners.get(target);
      if (owner !== null) totals.set(owner, (totals.get(owner) ?? 0) + 1);
      if (skip) continue;
      const dx = D[q] - at[0], dy = D[q + 1] - at[1], dz = D[q + 2] - at[2];
      const d2 = dx * dx + dy * dy + dz * dz;
      if (!(d2 <= r2)) continue;
      if (++count > maxSamples) return { status: 'sample-budget', parts: [], ids: [] };
      const coord = [Math.floor(dx / voxel), Math.floor(dy / voxel), Math.floor(dz / voxel)];
      const key = JSON.stringify([owner, ...coord]);
      if (!cells.has(key)) cells.set(key, { key, owner, ref, coord, ids: [], boundary: false });
      const cell = cells.get(key);
      cell.ids.push(i);
      cell.boundary ||= d2 >= edge;
      if (d2 < nearest) { nearest = d2; seed = cell; }
    }
    if (!seed) return { status: 'miss', parts: [], ids: [] };
    const queue = [seed], seen = new Set([seed.key]), ids = [];
    for (let i = 0; i < queue.length; i++) {
      const cell = queue[i];
      if (cell.boundary) return { status: 'touches-boundary', parts: [], ids: [] };
      for (const id of cell.ids) ids.push(id);
      const [x, y, z] = cell.coord;
      for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) for (let dz = -1; dz <= 1; dz++) {
        const key = JSON.stringify([seed.owner, x + dx, y + dy, z + dz]), neighbor = cells.get(key);
        if (neighbor && !seen.has(key)) { seen.add(key); queue.push(neighbor); }
      }
    }
    if (ids.length < minSamples) return { status: 'too-few-samples', parts: [], ids: [] };
    const parts = bySolid && seed.ref && totals.get(seed.owner) === ids.length ? [seed.ref] : [];
    return { status: 'suggested', parts, ids: ids.sort((a, b) => a - b) };
  }

  A.breakables = Object.freeze({ prepare, bind, suggest });
})(KIT);
